  ? { foldForQuote, quoteFoundIn, CONFIDENCE_FLOOR, MIN_EVIDENCE_CHARS,
      MAX_EVIDENCE_CHARS, MAX_EVIDENCE_RATIO, RATIO_APPLIES_FROM }
