// ---------------------------------------------------------------------------
// 2. normalise + first-pass spam screen (no model, no cost)
// ---------------------------------------------------------------------------
function clean(s, max) {
  return String(s == null ? '' : s).replace(/\u0000/g, '').trim().slice(0, max);
